# Generated by manage.py generate_test_cases.
from django.urls import reverse
from django.test import override_settings
from playwright.sync_api import expect
from bloomerp.config.definition import BloomerpConfig
from bloomerp.models.communication.voip import VoIPConnection
from bloomerp.tests.base import (
    BloomerpE2ETestCase,
    E2EAction,
    E2ERequestScenario,
)


class TestCreateVoIpconnectionViewE2E(BloomerpE2ETestCase):
    """Tests class `CreateVoIPConnectionView` from `bloomerp/views/communication/create_voip_connection.py`."""

    view_name = "add"

    def get_test_scenarios(self) -> list[E2ERequestScenario]:
        """Exercise the shared provider wizard's actual HTMX configuration and completion."""
        return [
            E2ERequestScenario(
                name="Configure a Twilio account",
                user=self.normal_user,
                url=reverse("voip_connections_add"),
                prepare=self.prepare_encryption,
                actions=[
                    E2EAction(
                        name="Select Twilio and save configuration",
                        execute=self.complete_wizard,
                        validators=self.verify_saved,
                    )
                ],
            )
        ]

    def prepare_encryption(self) -> None:
        """Use an isolated encryption key for the test account."""
        self.enterContext(
            override_settings(
                BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="e2e-voip-key")
            )
        )

    def complete_wizard(self) -> None:
        """Choose the carrier and submit its typed configuration through the browser."""
        self.page.locator('[data-value="twilio"]').click()
        self.page.locator('button[name="_wizard_action"][value="next"]').click()
        self.page.locator('#wizard-root input[name="name"]').fill("Browser Twilio")
        self.page.locator('#wizard-root input[name="account_sid"]').fill(
            "AC" + "1" * 32
        )
        self.page.locator('#wizard-root input[name="auth_token"]').fill(
            "e2e-private-token"
        )
        self.page.locator('#wizard-root input[name="public_url"]').fill(
            "https://example.test"
        )
        self.page.locator('button[name="_wizard_action"][value="next"]').click()

    def verify_saved(self) -> None:
        """Check completion exposes synchronization without echoing the submitted secret."""
        expect(self.page.locator("#wizard-root")).to_contain_text("Connection created")
        self.assertTrue(
            VoIPConnection.objects.filter(
                name="Browser Twilio", status="draft"
            ).exists()
        )
        self.assertNotIn(
            "e2e-private-token", self.page.locator("#wizard-root").inner_html()
        )
